27	function ProjectCardLogo({ projectId, name }: { projectId: string; name: string }) {
28	  const { data } = useSWR(`project-${projectId}-card-sources`, () =>
29	    sourcesApi.listByProject(projectId)
30	  );
31	  return <ProjectLogo name={name} sources={data?.data} size={40} />;
32	}
