34	/* ---------- Overflow Flow ---------- */
35	
36	const LINE_HEIGHT = 28; // matches leading-7 (1.75rem = 28px)
37	const MAX_LINES = 2;
38	const MAX_HEIGHT = LINE_HEIGHT * MAX_LINES;
39	
40	function FlowSection({
41	  label,
42	  moreHref,
43	  moreLabel,
44	  children,
45	}: {
46	  label: string;
47	  moreHref: string;
48	  moreLabel: string;
49	  children: React.ReactNode;
50	}) {
51	  const measureRef = useRef<HTMLDivElement>(null);
52	  const moreRef = useRef<HTMLSpanElement>(null);
53	  const [visibleCount, setVisibleCount] = useState<number | null>(null);
54	
55	  const items = React.Children.toArray(children);
56	
57	  const measure = useCallback(() => {
58	    const el = measureRef.current;
59	    if (!el) return;
60	    const nodes = el.children;
61	    const itemNodeCount = nodes.length - 2; // exclude label (first) and hidden "more…" span (last)
62	    // Check if everything fits without overflow
63	    if (el.scrollHeight <= MAX_HEIGHT + 4) {
64	      setVisibleCount(items.length);
65	      return;
66	    }
67	    // Measure actual "more…" link width
68	    const moreWidth = moreRef.current ? moreRef.current.offsetWidth + 8 : 52;
69	    const containerWidth = el.offsetWidth;
70	    // First pass: find all items that fit within MAX_HEIGHT (2 lines)
71	    let lastFitting = 0;
72	    for (let i = 1; i <= itemNodeCount; i++) {
73	      const node = nodes[i] as HTMLElement;
74	      if (node.offsetTop + node.offsetHeight > MAX_HEIGHT) break;
75	      lastFitting = i;
76	    }
77	    // Second pass: walk backward from lastFitting until "more…" fits after the item
78	    let count = lastFitting;
79	    while (count > 1) {
80	      const node = nodes[count] as HTMLElement;
81	      const nodeBottom = node.offsetTop + node.offsetHeight;
82	      // If this item is on line 1, "more…" can always wrap to line 2 — we're fine
83	      if (nodeBottom <= LINE_HEIGHT) break;
84	      // Item is on line 2 — check if "more…" fits after it on the same line
85	      const nodeRight = node.offsetLeft + node.offsetWidth;
86	      if (nodeRight + moreWidth <= containerWidth) break;
87	      count--;
88	    }
89	    setVisibleCount(Math.max(1, count));
90	  }, [items.length]);
91	
92	  useEffect(() => {
93	    const raf = requestAnimationFrame(measure);
94	    const obs = new ResizeObserver(measure);
95	    if (measureRef.current) obs.observe(measureRef.current);
96	    return () => {
97	      cancelAnimationFrame(raf);
98	      obs.disconnect();
99	    };
100	  }, [measure, items.length]);
101	
102	  const hasOverflow = visibleCount !== null && visibleCount < items.length;
103	  const displayed = visibleCount !== null ? items.slice(0, visibleCount) : items;
104	
105	  return (
106	    <div className="relative">
107	      {/* Hidden measurer — renders all items to find cutoff */}
108	      <div
109	        ref={measureRef}
110	        className="text-[13px] leading-7"
111	        style={{ position: "absolute", visibility: "hidden", top: 0, left: 0, right: 0, pointerEvents: "none" }}
112	        aria-hidden="true"
113	      >
114	        <span className="text-[11px] font-medium uppercase tracking-[0.08em] mr-1.5">
115	          {label}:
116	        </span>
117	        {items}
118	        {/* Hidden "more…" to measure its actual width */}
119	        <span ref={moreRef} className="inline-flex items-baseline text-[12px] font-medium whitespace-nowrap">
120	          {moreLabel}
121	        </span>
122	      </div>
123	      {/* Visible section */}
124	      <div className="text-[13px] leading-7">
125	        <span
126	          className="text-[11px] font-medium uppercase tracking-[0.08em] mr-1.5 text-text-muted"
127	          style={{ fontFamily: "var(--font-dm-sans)" }}
128	        >
129	          {label}:
130	        </span>
131	        {displayed}
132	        {hasOverflow && (
133	          <Link
134	            href={moreHref}
135	            className="inline-flex items-baseline text-[12px] font-medium hover:underline whitespace-nowrap text-beacon-accent"
136	          >
137	            {moreLabel}
138	          </Link>
139	        )}
140	      </div>
141	    </div>
142	  );
143	}
