145	/* ---------- Urgency Legend ---------- */
146	
147	function UrgencyLegend() {
148	  const { t } = useTranslation();
149	  const entries = [
150	    { key: "critical", label: t("projects.urgency.critical"), desc: t("projects.urgency.criticalDesc") },
151	    { key: "high", label: t("projects.urgency.high"), desc: t("projects.urgency.highDesc") },
152	    { key: "medium", label: t("projects.urgency.medium"), desc: t("projects.urgency.mediumDesc") },
153	    { key: "low", label: t("projects.urgency.low"), desc: t("projects.urgency.lowDesc") },
154	  ] as const;
155	
156	  return (
157	    <span className="relative inline-flex items-center group mr-1">
158	      <Info size={11} className="cursor-help text-text-muted" />
159	      <span
160	        className="absolute left-0 top-full mt-1 z-50 hidden group-hover:block rounded-lg shadow-lg py-2 px-3 bg-surface border-border"
161	        style={{ border: "1px solid var(--border)", width: 260 }}
162	      >
163	        <span className="block text-[10px] font-semibold uppercase tracking-wider mb-1.5 text-text-muted">
164	          {t("projects.urgencyLegend")}
165	        </span>
166	        {entries.map(({ key, label, desc }) => {
167	          const s = URGENCY_STYLES[key];
168	          const Icon = s.icon;
169	          return (
170	            <span key={key} className="flex items-start gap-2 mb-1 last:mb-0">
171	              <span
172	                className="inline-flex items-center justify-center rounded-full shrink-0 mt-0.5"
173	                style={{ backgroundColor: s.bg, border: `1px solid ${s.border}`, color: s.text, width: 16, height: 16 }}
174	              >
175	                <Icon size={9} />
176	              </span>
177	              <span className="flex flex-col">
178	                <span className="text-[11px] font-semibold leading-tight" style={{ color: s.text }}>{label}</span>
179	                <span className="text-[10px] leading-tight text-text-muted">{desc}</span>
180	              </span>
181	            </span>
182	          );
183	        })}
184	      </span>
185	    </span>
186	  );
187	}
