189	function ProjectFlowCard({ project, showExcluded }: { project: Project; showExcluded: boolean }) {
190	  const { t } = useTranslation();
191	  const [sourceCreateOpen, setSourceCreateOpen] = useState(false);
192	  const [editingSource, setEditingSource] = useState<Source | null>(null);
193	
194	  const { data: srcData, mutate: mutateSources } = useSWR(
195	    `project-${project.id}-card-sources`,
196	    () => sourcesApi.listByProject(project.id),
197	  );
198	  const sources = srcData?.data ?? [];
199	  const { data: relData } = useSWR(
200	    sources.length > 0 ? `project-${project.id}-card-releases-${sources.map(s => s.id).join(",")}` : null,
201	    async () => {
202	      const results = await Promise.all(
203	        sources.map((s) => releasesApi.listBySource(s.id, 1, 15, { include_excluded: true }))
204	      );
205	      return results.flatMap((r) => r.data ?? []);
206	    },
207	  );
208	  const allReleases = relData ?? [];
209	  const releases = showExcluded ? allReleases : allReleases.filter((r) => !r.excluded);
210	
211	  const sourceMap = useMemo(() => {
212	    const m = new Map<string, Source>();
213	    for (const s of sources) m.set(s.id, s);
214	    return m;
215	  }, [sources]);
216	
217	  return (
218	    <div
219	      className="rounded-md px-5 py-4 border-border bg-surface"
220	      style={{ border: "1px solid var(--border)" }}
221	    >
222	      {/* Header */}
223	      <div className="flex items-center justify-between mb-2">
224	        <div className="flex items-center gap-3 min-w-0">
225	          <ProjectCardLogo projectId={project.id} name={project.name} />
226	          <div className="min-w-0">
227	            <Link
228	              href={`/projects/${project.id}`}
229	              className="group inline-flex items-center gap-1.5 text-[16px] font-bold transition-colors text-beacon-accent"
230	              style={{ fontFamily: "var(--font-raleway)" }}
231	            >
232	              {project.name}
233	              <ArrowRight className="h-3.5 w-3.5 opacity-0 -translate-x-1 transition-all group-hover:opacity-100 group-hover:translate-x-0" />
234	            </Link>
235	            {project.description && (
236	              <p
237	                className="text-[13px] truncate text-text-secondary"
238	                style={{ fontFamily: "var(--font-dm-sans)" }}
239	              >
240	                {project.description}
241	              </p>
242	            )}
243	          </div>
244	        </div>
245	      </div>
246	
247	      {/* Sources chips */}
248	      <div className="flex flex-wrap items-center gap-1.5 mb-3">
249	        <span
250	          className="text-[11px] font-medium uppercase tracking-[0.08em] mr-0.5 text-text-muted"
251	          style={{ fontFamily: "var(--font-dm-sans)" }}
252	        >
253	          {t("projects.sources")}:
254	        </span>
255	        {sources.map((source) => (
256	          <button
257	            key={source.id}
258	            onClick={() => setEditingSource(source)}
259	            className="group/chip inline-flex items-center gap-1.5 rounded px-2 py-0.5 text-[12px] transition-colors hover:bg-mono-bg"
260	            style={{
261	              backgroundColor: source.last_error ? "var(--error-bg)" : "var(--background)",
262	              border: `1px solid ${source.last_error ? "var(--error-border)" : "var(--border)"}`,
263	            }}
264	            title={source.last_error ? `Error: ${source.last_error}` : undefined}
265	          >
266	            <span
267	              className="inline-block h-1.5 w-1.5 rounded-full shrink-0"
268	              style={{ backgroundColor: source.last_error ? "var(--error-text)" : source.enabled ? "var(--status-completed)" : "var(--text-muted)" }}
269	            />
270	            {(() => { const Icon = getProviderIcon(source.provider); return Icon ? <Icon size={12} className="shrink-0 text-text-muted" /> : null; })()}
271	            <span className="text-secondary-foreground" style={{ fontFamily: "'JetBrains Mono', monospace" }}>
272	              {source.repository}
273	            </span>
274	            {source.last_polled_at && (
275	              <span className="text-text-muted">
276	                {timeAgo(source.last_polled_at).replace(" ago", "")}
277	              </span>
278	            )}
279	            <Pencil className="h-2.5 w-2.5 hidden group-hover/chip:inline shrink-0 text-text-muted opacity-50" />
280	          </button>
281	        ))}
282	        <button
283	          onClick={() => setSourceCreateOpen(true)}
284	          className="inline-flex items-center gap-1 px-2 py-0.5 text-[12px] font-medium rounded border transition-colors hover:bg-mono-bg border-border text-text-muted"
285	          style={{
286	            fontFamily: "var(--font-dm-sans)",
287	          }}
288	        >
289	          <Plus className="h-3 w-3" />
290	          {t("projects.addSource")}
291	        </button>
292	      </div>
293	
294	      {/* Releases flow */}
295	      {releases.length > 0 && (
296	        <FlowSection label={t("projects.releases")} moreHref={`/releases?project=${project.id}`} moreLabel={t("projects.more")}>
297	          {releases.map((r) => {
298	            const src = sourceMap.get(r.source_id);
299	            return (
300	              <span key={r.id} className="inline-flex items-baseline mr-2.5">
301	                <Link
302	                  href={`/releases/${r.id}`}
303	                  className={r.excluded ? "" : "text-[#2563eb] hover:underline"}
304	                  style={{
305	                    fontFamily: "'JetBrains Mono', monospace",
306	                    fontSize: "12px",
307	                    ...(r.excluded ? { color: "var(--text-muted)" } : {}),
308	                  }}
309	                >
310	                  {r.version}
311	                </Link>
312	                {!r.excluded && r.semantic_release_status === "completed" && r.semantic_release_id && (() => {
313	                  return r.semantic_release_urgency ? (
314	                    <Link
315	                      href={`/projects/${project.id}/semantic-releases/${r.semantic_release_id}`}
316	                      className="ml-1 transition-colors"
317	                      title={`${r.semantic_release_urgency} — ${t("projects.viewReport")}`}
318	                    >
319	                      <UrgencyPill urgency={r.semantic_release_urgency} variant="icon-only" />
320	                    </Link>
321	                  ) : (
322	                    <Link
323	                      href={`/projects/${project.id}/semantic-releases/${r.semantic_release_id}`}
324	                      className="inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 ml-1 text-[10px] font-semibold transition-colors bg-muted text-text-secondary"
325	                      style={{ border: "1px solid rgba(107,114,128,0.18)", fontFamily: "var(--font-dm-sans)" }}
326	                      title={t("projects.viewReport")}
327	                    >
328	                      {t("projects.report")}
329	                    </Link>
330	                  );
331	                })()}
332	                {!r.excluded && (r.semantic_release_status === "pending" || r.semantic_release_status === "processing") && (
333	                  <span
334	                    className="inline-flex items-center gap-0.5 rounded px-1 py-0.5 ml-1 text-[10px]"
335	                    style={{ backgroundColor: "#fef9c3", color: "#92400e", fontFamily: "var(--font-dm-sans)" }}
336	                  >
337	                    <Loader2 size={10} className="animate-spin" />
338	                  </span>
339	                )}
340	                {src && (
341	                  <span
342	                    className="text-[11px] ml-1 hidden sm:inline text-text-muted"
343	                    style={r.excluded ? { opacity: 0.5 } : {}}
344	                  >
345	                    ({src.repository.split("/").pop()})
346	                  </span>
347	                )}
348	                <span
349	                  className="text-[11px] ml-1 text-text-muted"
350	                  style={r.excluded ? { opacity: 0.5 } : {}}
351	                >
352	                  {timeAgo(r.released_at || r.created_at).replace(" ago", "")}
353	                </span>
354	              </span>
355	            );
356	          })}
357	        </FlowSection>
358	      )}
359	
360	      {/* Add Source dialog */}
361	      <Dialog open={sourceCreateOpen} onOpenChange={setSourceCreateOpen}>
362	        <DialogContent className="sm:max-w-lg">
363	          <DialogHeader>
364	            <DialogTitle>{t("projects.addSource")}</DialogTitle>
365	          </DialogHeader>
366	          <SourceForm
367	            title={t("projects.addSource")}
368	            projectId={project.id}
369	            onSubmit={async (input) => {
370	              const res = await sourcesApi.create(project.id, input);
371	              if (res.data?.id) sourcesApi.poll(res.data.id).catch(() => {});
372	            }}
373	            onSuccess={() => {
374	              setSourceCreateOpen(false);
375	              mutateSources();
376	            }}
377	            onCancel={() => setSourceCreateOpen(false)}
378	          />
379	        </DialogContent>
380	      </Dialog>
381	
382	      {/* Edit Source dialog */}
383	      <Dialog
384	        open={!!editingSource}
385	        onOpenChange={(open) => { if (!open) setEditingSource(null); }}
386	      >
387	        <DialogContent className="sm:max-w-lg">
388	          <DialogHeader>
389	            <DialogTitle>{t("projects.editSource")}</DialogTitle>
390	          </DialogHeader>
391	          {editingSource && (
392	            <SourceForm
393	              key={editingSource.id}
394	              title={t("projects.editSource")}
395	              initial={editingSource}
396	              onSubmit={async (input) => {
397	                await sourcesApi.update(editingSource.id, input);
398	              }}
399	              onSuccess={() => {
400	                setEditingSource(null);
401	                mutateSources();
402	              }}
403	              onCancel={() => setEditingSource(null)}
404	            />
405	          )}
406	        </DialogContent>
407	      </Dialog>
408	    </div>
409	  );
410	}
