414	function ProjectCompactRow({ project, showExcluded }: { project: Project; showExcluded: boolean }) {
415	  const { t } = useTranslation();
416	  const router = useRouter();
417	  const { data: srcData } = useSWR(`project-${project.id}-card-sources`, () =>
418	    sourcesApi.listByProject(project.id)
419	  );
420	  const sources = srcData?.data ?? [];
421	  const { data: relData } = useSWR(
422	    sources.length > 0 ? `project-${project.id}-card-releases-${sources.map(s => s.id).join(",")}` : null,
423	    async () => {
424	      const results = await Promise.all(
425	        sources.map((s) => releasesApi.listBySource(s.id, 1, 5, { include_excluded: true }))
426	      );
427	      return results.flatMap((r) => r.data ?? []);
428	    },
429	  );
430	  const { data: srData } = useSWR(`project-${project.id}-card-sr`, () =>
431	    srApi.list(project.id, 1, 3)
432	  );
433	
434	  const allReleases = relData ?? [];
435	  const releases = showExcluded ? allReleases : allReleases.filter((r) => !r.excluded);
436	  const srItems = srData?.data ?? [];
437	  const latest = releases[0];
438	  const latestSr = srItems[0];
439	
440	  const sourceMap = useMemo(() => {
441	    const m = new Map<string, Source>();
442	    for (const s of sources) m.set(s.id, s);
443	    return m;
444	  }, [sources]);
445	
446	  const latestSrc = latest ? sourceMap.get(latest.source_id) : undefined;
447	  const latestIcon = latestSrc ? getProviderIcon(latestSrc.provider) : undefined;
448	
449	  return (
450	    <div
451	      onClick={() => router.push(`/projects/${project.id}`)}
452	      className="flex items-center gap-4 rounded-md px-4 py-2.5 transition-colors hover:bg-background cursor-pointer bg-surface"
453	      style={{ border: "1px solid var(--border)" }}
454	    >
455	      {/* Project name */}
456	      <span
457	        className="flex items-center gap-2 text-[14px] font-bold shrink-0 text-beacon-accent"
458	        style={{ fontFamily: "var(--font-raleway)", minWidth: "160px" }}
459	      >
460	        <ProjectLogo name={project.name} sources={sources} size={24} />
461	        {project.name}
462	      </span>
463	
464	      {/* Latest release */}
465	      <span className="flex items-center gap-1.5 shrink-0" style={{ minWidth: "140px" }}>
466	        {latest ? (
467	          <>
468	            <Link
469	              href={`/releases/${latest.id}`}
470	              onClick={(e) => e.stopPropagation()}
471	              className="inline-flex items-center rounded px-1.5 py-0.5 text-[12px] leading-none hover:ring-1 hover:ring-border transition-shadow bg-mono-bg text-secondary-foreground"
472	              style={{
473	                fontFamily: "'JetBrains Mono', monospace",
474	              }}
475	            >
476	              {latest.version}
477	            </Link>
478	            {latestIcon && latestIcon({ size: 12, className: "shrink-0 text-text-muted" })}
479	            {latest.semantic_release_status === "completed" && latest.semantic_release_id && (() => {
480	              return latest.semantic_release_urgency ? (
481	                <Link
482	                  href={`/projects/${project.id}/semantic-releases/${latest.semantic_release_id}`}
483	                  onClick={(e) => e.stopPropagation()}
484	                  className="transition-colors"
485	                  title={`${latest.semantic_release_urgency} — ${t("projects.viewReport")}`}
486	                >
487	                  <UrgencyPill urgency={latest.semantic_release_urgency} variant="icon-only" />
488	                </Link>
489	              ) : (
490	                <Link
491	                  href={`/projects/${project.id}/semantic-releases/${latest.semantic_release_id}`}
492	                  onClick={(e) => e.stopPropagation()}
493	                  className="inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 text-[10px] font-semibold transition-colors bg-muted text-text-secondary"
494	                  style={{ border: "1px solid rgba(107,114,128,0.18)", fontFamily: "var(--font-dm-sans)" }}
495	                  title={t("projects.viewReport")}
496	                >
497	                  {t("projects.report")}
498	                </Link>
499	              );
500	            })()}
501	            {(latest.semantic_release_status === "pending" || latest.semantic_release_status === "processing") && (
502	              <span
503	                className="inline-flex items-center gap-0.5 rounded px-1.5 py-0.5 text-[10px]"
504	                style={{ backgroundColor: "#fef9c3", color: "#92400e", fontFamily: "var(--font-dm-sans)" }}
505	              >
506	                <Loader2 size={10} className="animate-spin" />
507	              </span>
508	            )}
509	          </>
510	        ) : (
511	          <span className="text-[12px] italic text-text-muted">
512	            {t("projects.noReleases")}
513	          </span>
514	        )}
515	      </span>
516	
517	      {/* Summary */}
518	      <span className="flex items-center gap-1.5 flex-1 min-w-0">
519	        {latest?.semantic_release_status === "completed" ? (
520	          <>
521	            {latest.semantic_release_urgency && (
522	              <UrgencyPill urgency={latest.semantic_release_urgency} variant="text" className="shrink-0" />
523	            )}
524	            {latestSr?.report?.summary && (
525	              <span className="text-[11px] truncate text-text-muted">
526	                {latestSr.report.summary.length > 60
527	                  ? latestSr.report.summary.slice(0, 60) + "\u2026"
528	                  : latestSr.report.summary}
529	              </span>
530	            )}
531	          </>
532	        ) : (
533	          <span className="text-[12px] italic text-text-muted">
534	            {latest?.semantic_release_status ? latest.semantic_release_status : t("projects.noAnalysis")}
535	          </span>
536	        )}
537	      </span>
538	
539	      {/* Arrow */}
540	      <ArrowRight className="h-3.5 w-3.5 shrink-0 text-text-muted" />
541	    </div>
