  type: "source_release" | "semantic_release";
  project_ids?: string[];
  source_ids?: string[];
  version_filter?: string;
}

export interface BatchDeleteSubscriptionInput {
  ids: string[];
}

// --- Todo Types ---

export interface Todo {
  id: string;
  release_id?: string;
  semantic_release_id?: string;
  status: "pending" | "acknowledged" | "resolved";
  created_at: string;
  acknowledged_at?: string;
  resolved_at?: string;
  project_id?: string;
  project_name?: string;
  version?: string;
  provider?: string;
  repository?: string;
  source_url?: string;
  release_url?: string;
  urgency?: string;
  released_at?: string;
  todo_type?: "release" | "semantic";
}

// --- System Types ---

export interface HealthStatus {
  status: string;
  database: string;
}

export interface Stats {
  total_projects: number;
  active_sources: number;
  total_releases: number;
  pending_agent_runs: number;
  releases_this_week: number;
  attention_needed: number;
}

export interface TrendBucket {
  period: string;
  releases: number;
  semantic_releases: number;
}

export interface TrendData {
  granularity: string;
  buckets: TrendBucket[];
}

// --- Discovery Types ---

export interface DiscoverItem {
  name: string;
  full_name: string;
  description: string;
  stars: number;
  language?: string;
  url: string;
  avatar_url?: string;
  provider: "github" | "dockerhub";
}

// --- SSE Event Types ---

export type SSEEventType = "release" | "semantic_release";

interface SSEBase {
  id: string;
  timestamp: string;
}

export type SSEEvent =
  | (SSEBase & {
      type: "release";
      data: { id: string; source_id: string; version: string; created_at: string };
    })
  | (SSEBase & {
      type: "semantic_release";
      data: { id: string; project_id: string; version: string; status: string };
    });

// --- Onboarding Types ---

export interface OnboardScan {
  id: string;
  repo_url: string;
  status: "pending" | "processing" | "completed" | "failed";
  results?: ScannedDependency[];
  error?: string;
  created_at: string;
  started_at?: string;
  completed_at?: string;
}

export interface ScannedDependency {
  name: string;
  version: string;
  ecosystem: string;
  upstream_repo: string;
  provider: string;
}

export interface OnboardSelection {
  dep_name: string;
  upstream_repo: string;
  provider: string;
  project_id?: string;
  new_project_name?: string;
}

export interface OnboardApplyResult {
  created_projects: Project[];
  created_sources: Source[];
  skipped: string[];
}

export interface SuggestionItem {
  name: string;
  full_name: string;
  description: string;
  stars: number;
  language?: string;
  url: string;
  avatar_url?: string;
  provider: string;
  tracked: boolean;
}

export interface RepoItem {
  name: string;
  full_name: string;
  description: string;
  language?: string;
  url: string;
  pushed_at: string;
}

// --- Release Gate Types ---

export interface VersionMapping {
  pattern: string;
  template: string;
}

export interface ReleaseGate {
  id: string;
  project_id: string;
  required_sources?: string[];
  timeout_hours: number;
  version_mapping?: Record<string, VersionMapping>;
  nl_rule?: string;
  enabled: boolean;
  created_at: string;
  updated_at: string;
}

export interface ReleaseGateInput {
  required_sources?: string[];
  timeout_hours: number;
  version_mapping?: Record<string, VersionMapping>;
  nl_rule?: string;
  enabled: boolean;
}

export interface VersionReadiness {
  id: string;
  project_id: string;
  version: string;
  status: "pending" | "ready" | "timed_out";
  sources_met: string[];
  sources_missing: string[];
  nl_rule_passed?: boolean;
  timeout_at: string;
  opened_at?: string;
  agent_triggered: boolean;
  created_at: string;
  updated_at: string;
}

export interface GateEvent {
  id: string;
  version_readiness_id: string;
  project_id: string;
  version: string;
  event_type: string;
  source_id?: string;
  details?: Record<string, unknown>;
  created_at: string;
}

// --- API Keys ---

export interface ApiKey {
  id: string;
  name: string;
  prefix: string;
  key?: string; // only returned on create
  created_at: string;
  last_used_at?: string;
}

export interface ApiKeyCreateInput {
  name: string;
}

